WITH mentions AS (SELECT UNNEST([{'id': t.start_id, 'nm': t.start_name, 'ty': t.start_type}, {'id': t.end_id, 'nm': t.end_name, 'ty': t.end_type}]) AS m FROM "@receipt-triples:output" t) SELECT m.id AS __corvic_surrogate_id, m.id AS node_id, 'Merchant' AS node_type, min(m.nm) AS name, count(*) AS mention_count FROM mentions WHERE m.ty = 'Merchant' AND m.id IS NOT NULL AND m.id <> '' GROUP BY m.id